class Solution {
    public long minCost(int[] nums,int x){
        int n=nums.length;
        int[] best=nums.clone();
        long answer=0;
        for(int value:best)answer+=value;
        for(int rotations=1;rotations<n;rotations++){
            long current=(long)rotations*x;
            for(int i=0;i<n;i++){
                best[i]=Math.min(best[i],nums[(i-rotations+n)%n]);
                current+=best[i];
            }
            answer=Math.min(answer,current);
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    fun minCost(nums:IntArray,x:Int):Long{
        val n=nums.size;
        val best=nums.clone();
        var answer=best.sumOf{
            it.toLong()
        };
        for(rotations in 1 until n){
            var current=rotations.toLong()*x;
            for(i in 0 until n){
                best[i]=minOf(best[i],nums[(i-rotations+n)%n]);
                current+=best[i]
            };
            answer=minOf(answer,current)
        };
        return answer
    }
}

